INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('18cc500b-b03b-5dbd-9b98-5f5d5d924734', 'Canada Bill C-423 An Act respecting the fight against', 'Bill C-423 An Act respecting the fight against certain forms of modern slavery through the imposition of certain measures and amending the Customs Tariff', 'This enactment enacts the Modern Slavery Act, which imposes an obligation on certain entities to report on the measures taken to prevent and reduce the risk that forced labour or child labour is used at any step in the manufacture, production, growing, extraction or processing of goods in Canada or elsewhere by the entity or in the manufacture, production, growing, extraction or processing of goods imported into Canada by the entity. The Act provides for an inspection regime and gives the Minister the power to require an entity to provide certain information. This enactment also amends the Customs Tariff to allow for a prohibition on importation of goods manufactured or produced wholly or in part by forced labour or child labour.', 'This enactment enacts the Modern Slavery Act, which imposes an obligation on certain entities to report on the measures taken to prevent and reduce the risk that forced labour or child labour is used at any step in the manufacture, production, growing, extraction or processing of goods in Canada or elsewhere by the entity or in the manufacture, production, growing, extraction or processing of goods imported into Canada by the entity. The Act provides for an inspection regime and gives the Minister the power to require an entity to provide certain information. This enactment also amends the Customs Tariff to allow for a prohibition on importation of goods manufactured or produced wholly or in part by forced labour or child labour.', 'This enactment enacts the Modern Slavery Act, which imposes an obligation on certain entities to report on the measures taken to prevent and reduce the risk that forced labour or child labour is used at any step in the manufacture, production, growing, extraction or processing of goods in Canada or elsewhere by the entity or in the manufacture, production, growing, extraction or processing of goods imported into Canada by the entity. The Act provides for an inspection regime and gives the Minister the power to require an entity to provide certain information. This enactment also amends the Customs Tariff to allow for a prohibition on importation of goods manufactured or produced wholly or in part by forced labour or child labour.', 'Canada', 'climate', 'in_force', '2018-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_78', ARRAY['sdg8', 'regulations', 'mandatory', 'canada', 'disclosure', 'sdg12', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('fa035cb9-5601-5026-9f79-7966f941babc', 'Canada Pan-Canadian Framework on Clean Growth and Climate Change', 'Pan-Canadian Framework on Clean Growth and Climate Change', 'The plan is to grow the economy while reducing emissions and building resilience to adapt to a changing climate. Canada''s plan to address climate change and grow the economy. The Pan-Canadian Framework is a commitment to the world that Canada will do its part on climate change, and a plan to meet the needs of Canadians.', 'The plan is to grow the economy while reducing emissions and building resilience to adapt to a changing climate. Canada''s plan to address climate change and grow the economy. The Pan-Canadian Framework is a commitment to the world that Canada will do its part on climate change, and a plan to meet the needs of Canadians.', 'The plan is to grow the economy while reducing emissions and building resilience to adapt to a changing climate. Canada''s plan to address climate change and grow the economy. The Pan-Canadian Framework is a commitment to the world that Canada will do its part on climate change, and a plan to meet the needs of Canadians.', 'Canada', 'climate', 'in_force', '2016-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_15', ARRAY['sdg2', 'sdg13', 'sdg9', 'sdg11', 'voluntary', 'canada', 'disclosure', 'sdg12', 'sdg15', 'voluntary_frameworks']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8a1681e7-2620-5164-a7b3-425e31e22ae3', 'Canada National Instrument 58-101: Disclosure of Corporate Governance Practices', 'National Instrument 58-101: Disclosure of Corporate Governance Practices 2016', 'This Canadian National Instrument sets out the disclosure and filing requirements relating to corporate governance practices that apply to a reporting issuer other than: An investment fund or issuer of asset-backed securities.', 'This Canadian National Instrument sets out the disclosure and filing requirements relating to corporate governance practices that apply to a reporting issuer other than: An investment fund or issuer of asset-backed securities.', 'This Canadian National Instrument sets out the disclosure and filing requirements relating to corporate governance practices that apply to a reporting issuer other than: An investment fund or issuer of asset-backed securities.', 'Canada', 'climate', 'in_force', '2016-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_24', ARRAY['regulations', 'mandatory', 'sdg16', 'canada', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('775bd6fd-a0fa-5022-8dea-1a9f8fe1b4f4', 'Canada 03-M. Model Business Principles on Forced Labour, Labour', 'Resolution 16-03-M. Model Business Principles on Forced Labour, Labour Trafficking, and Illegal or Harmful Child Labour, 2016', 'Canadian Bar Assoc.''s 2016 Model Business Principles guide companies to combat forced labor, trafficking, and harmful child labor within their operations and supply chains. Six key sections outline practical steps for due diligence, remediation, advocacy, collaboration, monitoring, and reporting. These principles, adopted by numerous businesses and endorsed by UN bodies, serve as a valuable resource for responsible, ethical corporate practices.', 'Canadian Bar Assoc.''s 2016 Model Business Principles guide companies to combat forced labor, trafficking, and harmful child labor within their operations and supply chains. Six key sections outline practical steps for due diligence, remediation, advocacy, collaboration, monitoring, and reporting. These principles, adopted by numerous businesses and endorsed by UN bodies, serve as a valuable resource for responsible, ethical corporate practices.', 'Canadian Bar Assoc.''s 2016 Model Business Principles guide companies to combat forced labor, trafficking, and harmful child labor within their operations and supply chains. Six key sections outline practical steps for due diligence, remediation, advocacy, collaboration, monitoring, and reporting. These principles, adopted by numerous businesses and endorsed by UN bodies, serve as a valuable resource for responsible, ethical corporate practices.', 'Canada', 'climate', 'in_force', '2016-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_85', ARRAY['guidance_frameworks', 'sdg8', 'other sustainability policy', 'sdg17', 'sdg12', 'canada', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('af429340-b763-5432-bc45-fe86bc142ab6', 'Canada Extractive Sector Transparency Measures Act. S.C. 2014, c', 'The Extractive Sector Transparency Measures Act. S.C. 2014, c. 39, s. 376', 'An Act to implement Canada''s international commitments to participate in the fight against corruption through the imposition of measures applicable to the extractive sector.', 'An Act to implement Canada''s international commitments to participate in the fight against corruption through the imposition of measures applicable to the extractive sector.', 'An Act to implement Canada''s international commitments to participate in the fight against corruption through the imposition of measures applicable to the extractive sector.', 'Canada', 'climate', 'in_force', '2015-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_6', ARRAY['regulations', 'mandatory', 'sdg16', 'canada', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('be68eda7-2321-5d47-b833-44477409e6e0', 'Canada Doing Business the Canadian Way: A Strategy', 'Doing Business the Canadian Way: A Strategy to Advance Corporate Social Responsibility in Canada’s Extractive Sector Abroad', 'It is an enhanced CSR strategy that clearly demonstrates the Government'' expectation that Canadian companies will promote Canadian values and operate abroad with the highest ethical standards.', 'It is an enhanced CSR strategy that clearly demonstrates the Government'' expectation that Canadian companies will promote Canadian values and operate abroad with the highest ethical standards.', 'It is an enhanced CSR strategy that clearly demonstrates the Government'' expectation that Canadian companies will promote Canadian values and operate abroad with the highest ethical standards.', 'Canada', 'climate', 'in_force', '2014-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_11', ARRAY['regulations', 'mandatory', 'canada', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c7738445-fb74-533d-9f15-f19221a8e90a', 'Canada Primer for Environmental & Social Disclosure', 'A Primer for Environmental & Social Disclosure 2014', 'It discusses how capital providers and insurers are advancing the agenda and sets out some key principles for environmental and social business conduct. It discusses mandatory disclosure requirements, industry-specific key performance indicators and initiatives in other countries. It provides a discussion about voluntary reporting.', 'It discusses how capital providers and insurers are advancing the agenda and sets out some key principles for environmental and social business conduct. It discusses mandatory disclosure requirements, industry-specific key performance indicators and initiatives in other countries. It provides a discussion about voluntary reporting.', 'It discusses how capital providers and insurers are advancing the agenda and sets out some key principles for environmental and social business conduct. It discusses mandatory disclosure requirements, industry-specific key performance indicators and initiatives in other countries. It provides a discussion about voluntary reporting.', 'Canada', 'climate', 'in_force', '2014-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_16', ARRAY['guidance_frameworks', 'mandatory', 'sdg16', 'canada', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4dee917c-6e24-53a6-8e58-a4c373e1a33a', 'Canada Ontario Regulation ()', 'Ontario Regulation (235/14)', 'It requires plan administrators to file Statements of Investment Policies and Procedures ("SIPPs") with the regulator; which need to disclose whether they have taken ESG issues into consideration. Regulation 235/14 is an Amendment to Regulation 909 under the Pension Benefits Act: Disclosure of Environmental, Social and Governance Factors in Statements of Investment Policies and Procedures. Statements requires plan assets to be invested in accordance with the SIPP; require SIPPs to include information about whether, and if so, how, ESG factors are incorporated; and, requires annual statements to members to include information about the purpose of SIPPs. The regulation includes amendments that require plan administrators to provide written statements to former members and retired members, containing prescribed information about the pension plan and their benefits. The regulation also includes amendments to make it easier for individuals to transfer the commuted value of their pension benefits from an Ontario plan to a plan elsewhere in Canada when they change employment, allowing individuals to consolidate their pension benefits if the receiving plan so allows.', 'It requires plan administrators to file Statements of Investment Policies and Procedures ("SIPPs") with the regulator; which need to disclose whether they have taken ESG issues into consideration. Regulation 235/14 is an Amendment to Regulation 909 under the Pension Benefits Act: Disclosure of Environmental, Social and Governance Factors in Statements of Investment Policies and Procedures. Statements requires plan assets to be invested in accordance with the SIPP; require SIPPs to include information about whether, and if so, how, ESG factors are incorporated; and, requires annual statements to members to include information about the purpose of SIPPs. The regulation includes amendments that require plan administrators to provide written statements to former members and retired members, containing prescribed information about the pension plan and their benefits. The regulation also includes amendments to make it easier for individuals to transfer the commuted value of their pension benefits from an Ontario plan to a plan elsewhere in Canada when they change employment, allowing individuals to consolidate their pension benefits if the receiving plan so allows.', 'It requires plan administrators to file Statements of Investment Policies and Procedures ("SIPPs") with the regulator; which need to disclose whether they have taken ESG issues into consideration. Regulation 235/14 is an Amendment to Regulation 909 under the Pension Benefits Act: Disclosure of Environmental, Social and Governance Factors in Statements of Investment Policies and Procedures. Statements requires plan assets to be invested in accordance with the SIPP; require SIPPs to include information about whether, and if so, how, ESG factors are incorporated; and, requires annual statements to members to include information about the purpose of SIPPs. The regulation includes amendments that require plan administrators to provide written statements to former members and retired members, containing prescribed information about the pension plan and their benefits. The regulation also includes amendments to make it easier for individuals to transfer the commuted value of their pension benefits from an Ontario plan to a plan elsewhere in Canada when they change employment, allowing individuals to consolidate their pension benefits if the receiving plan so allows.', 'Canada', 'social', 'in_force', '2014-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_26', ARRAY['sdg8', 'other sustainability policy', 'regulations', 'mandatory', 'sdg16', 'canada']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('24fb0555-7d6f-5e86-bb4f-adc49b5514e7', 'Canada Management''s Discussion and Analysis - Guidance on preparation', 'Management''s Discussion and Analysis - Guidance on preparation and disclosure', 'The purpose of this publication is to enable preparers, management, audit committee members, and boards of directors of all companies and other entities to prepare, present and review a useful MD&A in a way that maximizes value for primary users of a company’s financial reports; namely, investors, investor analysts, lenders and other creditors.', 'The purpose of this publication is to enable preparers, management, audit committee members, and boards of directors of all companies and other entities to prepare, present and review a useful MD&A in a way that maximizes value for primary users of a company’s financial reports; namely, investors, investor analysts, lenders and other creditors.', 'The purpose of this publication is to enable preparers, management, audit committee members, and boards of directors of all companies and other entities to prepare, present and review a useful MD&A in a way that maximizes value for primary users of a company’s financial reports; namely, investors, investor analysts, lenders and other creditors.', 'Canada', 'climate', 'in_force', '2014-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_43', ARRAY['guidance_frameworks', 'mandatory', 'canada', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
