INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('88f0886b-88c3-5544-9474-2042b570d718', 'Canada Corporate Social Responsibility (CSR). Implementation Guide for Canadian', 'Corporate Social Responsibility (CSR). Implementation Guide for Canadian Business', 'This guide is a primer on corporate social responsibility. It contains information on how to assess the effects of business activities on others, develop and implement a corporate social responsibility strategy and commitments, and measure, evaluate and report on performance and engage with stakeholders.', 'This guide is a primer on corporate social responsibility. It contains information on how to assess the effects of business activities on others, develop and implement a corporate social responsibility strategy and commitments, and measure, evaluate and report on performance and engage with stakeholders.', 'This guide is a primer on corporate social responsibility. It contains information on how to assess the effects of business activities on others, develop and implement a corporate social responsibility strategy and commitments, and measure, evaluate and report on performance and engage with stakeholders.', 'Canada', 'climate', 'in_force', '2014-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_9', ARRAY['regulations', 'mandatory', 'canada', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5b036a9b-a369-5505-a7f6-f37a9d892665', 'Canada Corporate Governance Guideline', 'Corporate Governance Guideline 2013', 'The purpose of this guideline is to communicate OSFI’s expectations with respect to corporate governance of federally-regulated financial institutions (FRFIs). It applies to all FRFIs other than the branch operations of foreign banks and foreign insurance companies.', 'The purpose of this guideline is to communicate OSFI’s expectations with respect to corporate governance of federally-regulated financial institutions (FRFIs). It applies to all FRFIs other than the branch operations of foreign banks and foreign insurance companies.', 'The purpose of this guideline is to communicate OSFI’s expectations with respect to corporate governance of federally-regulated financial institutions (FRFIs). It applies to all FRFIs other than the branch operations of foreign banks and foreign insurance companies.', 'Canada', 'governance', 'in_force', '2013-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_31', ARRAY['guidance_frameworks', 'sdg16', 'canada', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('da3df3f7-fd78-5d4e-913f-0cabf22ee2fb', 'Canada Canadian Environmental Assessment Act, 2012, SC 2012, c', 'Canadian Environmental Assessment Act, 2012, SC 2012, c 19, s 52', 'The Act looks at respecting the environmental assessment of certain activities and the prevention of significant adverse environmental effects The Act requires federal departments, including Environment Canada , agencies, and Crown corporations to conduct environmental assessments for proposed projects where the federal government is the proponent or where the project involves federal funding, permits, or licensing.', 'The Act looks at respecting the environmental assessment of certain activities and the prevention of significant adverse environmental effects The Act requires federal departments, including Environment Canada , agencies, and Crown corporations to conduct environmental assessments for proposed projects where the federal government is the proponent or where the project involves federal funding, permits, or licensing.', 'The Act looks at respecting the environmental assessment of certain activities and the prevention of significant adverse environmental effects The Act requires federal departments, including Environment Canada , agencies, and Crown corporations to conduct environmental assessments for proposed projects where the federal government is the proponent or where the project involves federal funding, permits, or licensing.', 'Canada', 'governance', 'in_force', '2012-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_35', ARRAY['regulations', 'mandatory', 'canada', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e2546b22-6dcf-5f10-a09e-55522054bb2b', 'Canada National Instrument 51-102 Continuous Disclosure Obligations', 'National Instrument 51-102 Continuous Disclosure Obligations - for financial years beginning on or after January 1, 2011 (unofficial consolidation)', 'This document is one of two versions of unofficial consolidations of National Instrument 51-102 Continuous Disclosure Obligations and its companion policy prepared as of October 31, 2011. This version generally applies to financial years beginning on or after January 1, 2011, as described more fully below. The document  reflects amendments relating to the changeover to International Financial Reporting Standards in Canada that were included in an amendment instrument published in the December 10, 2010 Ontario Securities Commission Bulletin. It applies in relation to documents required to be prepared, filed, delivered or sent under the Instrument for periods relating to financial years beginning on or after January 1, 2011, other than for periods to which section 77 of the amendment instrument applies.', 'This document is one of two versions of unofficial consolidations of National Instrument 51-102 Continuous Disclosure Obligations and its companion policy prepared as of October 31, 2011. This version generally applies to financial years beginning on or after January 1, 2011, as described more fully below. The document  reflects amendments relating to the changeover to International Financial Reporting Standards in Canada that were included in an amendment instrument published in the December 10, 2010 Ontario Securities Commission Bulletin. It applies in relation to documents required to be prepared, filed, delivered or sent under the Instrument for periods relating to financial years beginning on or after January 1, 2011, other than for periods to which section 77 of the amendment instrument applies.', 'This document is one of two versions of unofficial consolidations of National Instrument 51-102 Continuous Disclosure Obligations and its companion policy prepared as of October 31, 2011. This version generally applies to financial years beginning on or after January 1, 2011, as described more fully below. The document  reflects amendments relating to the changeover to International Financial Reporting Standards in Canada that were included in an amendment instrument published in the December 10, 2010 Ontario Securities Commission Bulletin. It applies in relation to documents required to be prepared, filed, delivered or sent under the Instrument for periods relating to financial years beginning on or after January 1, 2011, other than for periods to which section 77 of the amendment instrument applies.', 'Canada', 'climate', 'in_force', '2011-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_17', ARRAY['mandatory', 'mandatory_regulations', 'canada', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('6041a690-1b4c-5921-80a5-2bbec8c19451', 'Canada National Instrument 43-101 Standards of Disclosure for Mineral', 'National Instrument 43-101 Standards of Disclosure for Mineral Projects', 'This Canadian national instrument provides rules and guidelines for reporting scientific and technical information related to mineral projects owned or explored by entities in oral statements, websites, written reports, offering documents, press releases and continuous disclosure required under Applicable Securities Laws in Canada. It applies to Canadian entities as well as foreign-owned entities who have securities that trade on stock exchanges or over-the-counter (OTC) markets overseen by the Canadian Securities Administrators.', 'This Canadian national instrument provides rules and guidelines for reporting scientific and technical information related to mineral projects owned or explored by entities in oral statements, websites, written reports, offering documents, press releases and continuous disclosure required under Applicable Securities Laws in Canada. It applies to Canadian entities as well as foreign-owned entities who have securities that trade on stock exchanges or over-the-counter (OTC) markets overseen by the Canadian Securities Administrators.', 'This Canadian national instrument provides rules and guidelines for reporting scientific and technical information related to mineral projects owned or explored by entities in oral statements, websites, written reports, offering documents, press releases and continuous disclosure required under Applicable Securities Laws in Canada. It applies to Canadian entities as well as foreign-owned entities who have securities that trade on stock exchanges or over-the-counter (OTC) markets overseen by the Canadian Securities Administrators.', 'Canada', 'climate', 'in_force', '2011-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_23', ARRAY['voluntary_frameworks', 'voluntary', 'canada', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('86acbdf8-fddf-5370-8746-707d8e39fa64', 'Canada CSA Staff Notice 51-333 Environmental Reporting Guidance', 'CSA Staff Notice 51-333 Environmental Reporting Guidance', 'The CSA Staff Notice 51-333 Environmental Reporting Guidance is intended to assist issuers in: (1) determining what information about environmental matters needs to be disclosed, and (2) enhancing or supplementing their disclosure regarding environmental matters, as necessary.', 'The CSA Staff Notice 51-333 Environmental Reporting Guidance is intended to assist issuers in: (1) determining what information about environmental matters needs to be disclosed, and (2) enhancing or supplementing their disclosure regarding environmental matters, as necessary.', 'The CSA Staff Notice 51-333 Environmental Reporting Guidance is intended to assist issuers in: (1) determining what information about environmental matters needs to be disclosed, and (2) enhancing or supplementing their disclosure regarding environmental matters, as necessary.', 'Canada', 'climate', 'in_force', '2010-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_1', ARRAY['guidance_frameworks', 'sdg7', 'sdg11', 'mandatory', 'canada', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3215d298-19cd-5cde-a775-1f5b2db52145', 'Canada 2010 Principles for Governance Monitoring, Voting and Shareholder', '2010 Principles for Governance Monitoring, Voting and Shareholder Engagement- Canadian Coalition for Good Governance - December (2010)', 'In 2005, CCGG published its Statement of Principles Regarding Member Activism outlining principles and best practices for shareholder involvement with Canadian companies in which they are invested. The purpose of this document is to update those principles and to provide guidance to institutional investors on active share ownership and its benefits.', 'In 2005, CCGG published its Statement of Principles Regarding Member Activism outlining principles and best practices for shareholder involvement with Canadian companies in which they are invested. The purpose of this document is to update those principles and to provide guidance to institutional investors on active share ownership and its benefits.', 'In 2005, CCGG published its Statement of Principles Regarding Member Activism outlining principles and best practices for shareholder involvement with Canadian companies in which they are invested. The purpose of this document is to update those principles and to provide guidance to institutional investors on active share ownership and its benefits.', 'Canada', 'governance', 'in_force', '2010-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_19', ARRAY['guidance_frameworks', 'sdg16', 'canada', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2a75dc65-a5a2-5dc1-8611-12f9e30c0802', 'Canada Occupational Health and Safety Regulations SOR/86-304', 'Canada Occupational Health and Safety Regulations SOR/86-304', 'The Canada Occupational Health and Safety Regulations SOR/86-304 are federal regulations in Canada that set out the requirements for ensuring the health and safety of workers in the workplace. The regulations apply to all employers and employees under federal jurisdiction, including those in industries such as transportation, telecommunications, banking, and interprovincial trade. Under the regulations, businesses have a number of obligations to protect the health and safety of their workers. These include providing a safe and healthy work environment, developing and implementing health and safety programs, providing training and supervision to workers, and ensuring that workers have access to the necessary equipment and protective gear. Businesses are also required to identify and assess workplace hazards, and to take measures to control or eliminate these hazards. They must develop emergency response plans and procedures, and conduct regular inspections and audits to ensure compliance with the regulations. Employers must also report all workplace accidents and incidents to the appropriate authorities, and keep accurate records of all health and safety activities and incidents. They must also cooperate with government inspectors and comply with all orders and directives issued by these inspectors.', 'The Canada Occupational Health and Safety Regulations SOR/86-304 are federal regulations in Canada that set out the requirements for ensuring the health and safety of workers in the workplace. The regulations apply to all employers and employees under federal jurisdiction, including those in industries such as transportation, telecommunications, banking, and interprovincial trade. Under the regulations, businesses have a number of obligations to protect the health and safety of their workers. These include providing a safe and healthy work environment, developing and implementing health and safety programs, providing training and supervision to workers, and ensuring that workers have access to the necessary equipment and protective gear. Businesses are also required to identify and assess workplace hazards, and to take measures to control or eliminate these hazards. They must develop emergency response plans and procedures, and conduct regular inspections and audits to ensure compliance with the regulations. Employers must also report all workplace accidents and incidents to the appropriate authorities, and keep accurate records of all health and safety activities and incidents. They must also cooperate with government inspectors and comply with all orders and directives issued by these inspectors.', 'The Canada Occupational Health and Safety Regulations SOR/86-304 are federal regulations in Canada that set out the requirements for ensuring the health and safety of workers in the workplace. The regulations apply to all employers and employees under federal jurisdiction, including those in industries such as transportation, telecommunications, banking, and interprovincial trade. Under the regulations, businesses have a number of obligations to protect the health and safety of their workers. These include providing a safe and healthy work environment, developing and implementing health and safety programs, providing training and supervision to workers, and ensuring that workers have access to the necessary equipment and protective gear. Businesses are also required to identify and assess workplace hazards, and to take measures to control or eliminate these hazards. They must develop emergency response plans and procedures, and conduct regular inspections and audits to ensure compliance with the regulations. Employers must also report all workplace accidents and incidents to the appropriate authorities, and keep accurate records of all health and safety activities and incidents. They must also cooperate with government inspectors and comply with all orders and directives issued by these inspectors.', 'Canada', 'climate', 'in_force', '2009-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_45', ARRAY['sdg4', 'sdg8', 'other sustainability policy', 'regulations', 'sdg11', 'mandatory', 'canada', 'sdg9', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('00490b37-3fac-5dd0-82cd-32817c7f8f62', 'Canada Coal Mining Occupational Health and Safety Regulations', 'Coal Mining Occupational Health and Safety Regulations', 'The Coal Mining Occupational Health and Safety Regulations of Canada, enacted in 2009, outlines the obligations of businesses involved in coal mining. The regulations require employers to identify and assess potential health and safety hazards, develop a written health and safety program, provide training to workers, establish emergency response procedures, and maintain accurate records. The regulations also establish requirements for ventilation, fire prevention, and personal protective equipment. Additionally, employers must ensure that all equipment and machinery used in the mining process is safe and maintained properly, and they must provide regular health and safety inspections of the workplace.', 'The Coal Mining Occupational Health and Safety Regulations of Canada, enacted in 2009, outlines the obligations of businesses involved in coal mining. The regulations require employers to identify and assess potential health and safety hazards, develop a written health and safety program, provide training to workers, establish emergency response procedures, and maintain accurate records. The regulations also establish requirements for ventilation, fire prevention, and personal protective equipment. Additionally, employers must ensure that all equipment and machinery used in the mining process is safe and maintained properly, and they must provide regular health and safety inspections of the workplace.', 'The Coal Mining Occupational Health and Safety Regulations of Canada, enacted in 2009, outlines the obligations of businesses involved in coal mining. The regulations require employers to identify and assess potential health and safety hazards, develop a written health and safety program, provide training to workers, establish emergency response procedures, and maintain accurate records. The regulations also establish requirements for ventilation, fire prevention, and personal protective equipment. Additionally, employers must ensure that all equipment and machinery used in the mining process is safe and maintained properly, and they must provide regular health and safety inspections of the workplace.', 'Canada', 'climate', 'in_force', '2009-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_54', ARRAY['sdg4', 'sdg8', 'other sustainability policy', 'regulations', 'mandatory', 'canada', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f67c43a9-4722-5bdb-a0d7-883facc32c73', 'Canada Building the Canadian Advantage: A Corporate Social Responsibility', 'Building the Canadian Advantage: A Corporate Social Responsibility (CSR) Strategy for the Canadian International Extractive Sector', 'The strategy encourages voluntary compliance with internationally-recognized CSR tools and guidelines, the Government of Canada promotes GRI, which can help Canadian companies measure and manage their economic, environmental, social and governance performance. This is meant to result in enhanced accountability and transparency through the reporting process can lead to good CSR performance and encourage market-based rewards for Canadian companies.', 'The strategy encourages voluntary compliance with internationally-recognized CSR tools and guidelines, the Government of Canada promotes GRI, which can help Canadian companies measure and manage their economic, environmental, social and governance performance. This is meant to result in enhanced accountability and transparency through the reporting process can lead to good CSR performance and encourage market-based rewards for Canadian companies.', 'The strategy encourages voluntary compliance with internationally-recognized CSR tools and guidelines, the Government of Canada promotes GRI, which can help Canadian companies measure and manage their economic, environmental, social and governance performance. This is meant to result in enhanced accountability and transparency through the reporting process can lead to good CSR performance and encourage market-based rewards for Canadian companies.', 'Canada', 'climate', 'in_force', '2009-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_8', ARRAY['regulations', 'mandatory', 'sdg16', 'canada', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING