INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('79fb0ca6-aeec-5e9c-b703-95c760bc2779', 'Canada Federal Sustainable Development Act (FSDA)', 'Federal Sustainable Development Act (FSDA)', 'The purpose of this Act is to provide the legal framework for developing and implementing a Federal Sustainable Development Strategy that will make environmental decision-making more transparent and accountable to Parliament.', 'The purpose of this Act is to provide the legal framework for developing and implementing a Federal Sustainable Development Strategy that will make environmental decision-making more transparent and accountable to Parliament.', 'The purpose of this Act is to provide the legal framework for developing and implementing a Federal Sustainable Development Strategy that will make environmental decision-making more transparent and accountable to Parliament.', 'Canada', 'climate', 'in_force', '2008-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_12', ARRAY['sdg13', 'regulations', 'mandatory', 'sdg16', 'sdg12', 'disclosure', 'canada']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d14439e1-36fd-52fc-93a7-9949bd1c93ba', 'Canada TSX Guide to Good Disclosure for National Instrument', 'TSX Guide to Good Disclosure for National Instrument 58-101 Disclosure of Corporate Governance Practices (NI 58-101) and Multilateral Instrument 52-110 – Audit Committees (MI 52-110) (As of January 2006)', 'This document presents the TSX Guide to Good Disclosure for National Instrument 58-101 Disclosure of Corporate Governance Practices (NI 58-101) and Multilateral Instrument 52-110 – Audit Committees (MI 52-110).', 'This document presents the TSX Guide to Good Disclosure for National Instrument 58-101 Disclosure of Corporate Governance Practices (NI 58-101) and Multilateral Instrument 52-110 – Audit Committees (MI 52-110).', 'This document presents the TSX Guide to Good Disclosure for National Instrument 58-101 Disclosure of Corporate Governance Practices (NI 58-101) and Multilateral Instrument 52-110 – Audit Committees (MI 52-110).', 'Canada', 'governance', 'in_force', '2006-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_21', ARRAY['regulations', 'mandatory', 'sdg16', 'canada', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('abf9103e-082a-5140-bd58-16121d92c76a', 'Canada National Policy 58-201: Corporate Governance Guidelines', 'National Policy 58-201: Corporate Governance Guidelines', 'This Policy provides guidance on corporate governance practices which have been formulated to: (1) achieve a balance between providing protection to investors and fostering fair and efficient capital markets and confidence in capital markets; (2) be sensitive to the realities of the greater numbers of small companies and controlled companies in the Canadian corporate landscape; (3) take into account the impact of corporate governance developments in the U.S. and around the world; and (4) recognize that corporate governance is evolving.', 'This Policy provides guidance on corporate governance practices which have been formulated to: (1) achieve a balance between providing protection to investors and fostering fair and efficient capital markets and confidence in capital markets; (2) be sensitive to the realities of the greater numbers of small companies and controlled companies in the Canadian corporate landscape; (3) take into account the impact of corporate governance developments in the U.S. and around the world; and (4) recognize that corporate governance is evolving.', 'This Policy provides guidance on corporate governance practices which have been formulated to: (1) achieve a balance between providing protection to investors and fostering fair and efficient capital markets and confidence in capital markets; (2) be sensitive to the realities of the greater numbers of small companies and controlled companies in the Canadian corporate landscape; (3) take into account the impact of corporate governance developments in the U.S. and around the world; and (4) recognize that corporate governance is evolving.', 'Canada', 'nature', 'in_force', '2005-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_29', ARRAY['guidance_frameworks', 'sdg16', 'canada', 'disclosure', 'sdg15', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f62bafb4-62a2-54e8-a8f7-c8334443ef1a', 'Canada National Instrument 58-101: Disclosure of Corporate Governance Practices', 'National Instrument 58-101: Disclosure of Corporate Governance Practices 2005', 'The amendments are intended to increase transparency for investors and other stakeholders regarding the representation of women on boards of directors and in senior management. The securities regulatory authorities in Manitoba, New Brunswick, Newfoundland and Labrador, Northwest Territories, Nova Scotia, Nunavut, Ontario, Québec and Saskatchewan (“participating jurisdictions”) announced today the final implementation of amendments to National Instrument 58-101 Disclosure of Corporate Governance Practices and Form 58-101F1 Corporate Governance Disclosure. Provided all necessary Ministerial approvals are obtained, these rule amendments will come into effect on December 31, 2014, in time for the 2015 proxy season. Transparency is intended to assist investors in making investment and voting decisions and will apply to all non-venture issuers reporting in the participating jurisdictions.', 'The amendments are intended to increase transparency for investors and other stakeholders regarding the representation of women on boards of directors and in senior management. The securities regulatory authorities in Manitoba, New Brunswick, Newfoundland and Labrador, Northwest Territories, Nova Scotia, Nunavut, Ontario, Québec and Saskatchewan (“participating jurisdictions”) announced today the final implementation of amendments to National Instrument 58-101 Disclosure of Corporate Governance Practices and Form 58-101F1 Corporate Governance Disclosure. Provided all necessary Ministerial approvals are obtained, these rule amendments will come into effect on December 31, 2014, in time for the 2015 proxy season. Transparency is intended to assist investors in making investment and voting decisions and will apply to all non-venture issuers reporting in the participating jurisdictions.', 'The amendments are intended to increase transparency for investors and other stakeholders regarding the representation of women on boards of directors and in senior management. The securities regulatory authorities in Manitoba, New Brunswick, Newfoundland and Labrador, Northwest Territories, Nova Scotia, Nunavut, Ontario, Québec and Saskatchewan (“participating jurisdictions”) announced today the final implementation of amendments to National Instrument 58-101 Disclosure of Corporate Governance Practices and Form 58-101F1 Corporate Governance Disclosure. Provided all necessary Ministerial approvals are obtained, these rule amendments will come into effect on December 31, 2014, in time for the 2015 proxy season. Transparency is intended to assist investors in making investment and voting decisions and will apply to all non-venture issuers reporting in the participating jurisdictions.', 'Canada', 'climate', 'in_force', '2005-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_36', ARRAY['sdg14', 'regulations', 'mandatory', 'sdg5', 'sdg16', 'canada', 'disclosure', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c2bcafbe-4f22-522a-9fad-514caa526158', 'Canada Policy Statement on Timely Disclosure', 'Policy Statement on Timely Disclosure', 'This policy document requires publicly listed companies to immediately disclose material information in a timely manner that could significantly affect the market price or value of the company’s listed securities, specifies inclusion of ESG issues.', 'This policy document requires publicly listed companies to immediately disclose material information in a timely manner that could significantly affect the market price or value of the company’s listed securities, specifies inclusion of ESG issues.', 'This policy document requires publicly listed companies to immediately disclose material information in a timely manner that could significantly affect the market price or value of the company’s listed securities, specifies inclusion of ESG issues.', 'Canada', 'climate', 'in_force', '2004-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_3', ARRAY['sdg10', 'mandatory', 'mandatory_regulations', 'sdg12', 'disclosure', 'canada']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7fdfc779-ffc2-5f6b-8589-e391b3b9d34b', 'Canada Corporate Governance. A Guide to Good Disclosure', 'Corporate Governance. A Guide to Good Disclosure', 'This guide helps issuers prepare meaningful disclosure that complies with TSX requirements. It also suggests other information you can include to improve the quality of your communication with investors.', 'This guide helps issuers prepare meaningful disclosure that complies with TSX requirements. It also suggests other information you can include to improve the quality of your communication with investors.', 'This guide helps issuers prepare meaningful disclosure that complies with TSX requirements. It also suggests other information you can include to improve the quality of your communication with investors.', 'Canada', 'governance', 'in_force', '2003-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_74', ARRAY['mandatory', 'sdg16', 'mandatory_regulations', 'canada', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('59c20310-bd9e-5356-8713-2ffea8dc6443', 'Canada Public Accountability Statements (Banks, Insurance Companies, Trust', 'Public Accountability Statements (Banks, Insurance Companies, Trust and Loan Companies) Regulations', 'This regulation requires that financial institutions with less than one billion dollars in equity, other than foreign institutions doing business exclusively outside of Canada, are affiliates of a declarant required to publish a public accountability statement. A list of the declarant''s affiliates must be included in the public accountability statement. It must also include information about their philanthropic activities other than charitable donations during the time period.', 'This regulation requires that financial institutions with less than one billion dollars in equity, other than foreign institutions doing business exclusively outside of Canada, are affiliates of a declarant required to publish a public accountability statement. A list of the declarant''s affiliates must be included in the public accountability statement. It must also include information about their philanthropic activities other than charitable donations during the time period.', 'This regulation requires that financial institutions with less than one billion dollars in equity, other than foreign institutions doing business exclusively outside of Canada, are affiliates of a declarant required to publish a public accountability statement. A list of the declarant''s affiliates must be included in the public accountability statement. It must also include information about their philanthropic activities other than charitable donations during the time period.', 'Canada', 'governance', 'in_force', '2002-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_2', ARRAY['regulations', 'mandatory', 'sdg16', 'canada', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f23d49a3-f575-5001-baa1-f085b5216b12', 'Canada Corporate Governance Policy - Proposed New Disclosure Requirement', 'Corporate Governance Policy - Proposed New Disclosure Requirement and Amended Guidelines', 'In July 2000, the Toronto Stock Exchange (the “TSX”), the TSX Venture Exchange and the Canadian Institute of Chartered Accountants mandated the Joint Committee on Corporate Governance (the “JCCG”) to review the state of corporate governance practices in Canada and recommend changes that will assure the ongoing development of Canadian corporate governance standards as among the best in the world. The JCCG tabled its preliminary report in March 2001 and, following extensive comments from various stakeholders, issued its final report in November 2001 (the “JCCG Report”). The Joint Committee on Corporate Governance Report contains 15 recommendations, the majority of which propose modifications to the existing TSX Corporate Governance Guidelines (the “Guidelines”) introduced in 1995. In response, the TSX is proposing that certain amendments be made to the Guidelines. Other recommendations of the JCCG will be reflected in Practice Notes to the Guidelines. The TSX has also amended the disclosure requirements in the TSX Company Manual, principally by consolidating sections 473 and 475.', 'In July 2000, the Toronto Stock Exchange (the “TSX”), the TSX Venture Exchange and the Canadian Institute of Chartered Accountants mandated the Joint Committee on Corporate Governance (the “JCCG”) to review the state of corporate governance practices in Canada and recommend changes that will assure the ongoing development of Canadian corporate governance standards as among the best in the world. The JCCG tabled its preliminary report in March 2001 and, following extensive comments from various stakeholders, issued its final report in November 2001 (the “JCCG Report”). The Joint Committee on Corporate Governance Report contains 15 recommendations, the majority of which propose modifications to the existing TSX Corporate Governance Guidelines (the “Guidelines”) introduced in 1995. In response, the TSX is proposing that certain amendments be made to the Guidelines. Other recommendations of the JCCG will be reflected in Practice Notes to the Guidelines. The TSX has also amended the disclosure requirements in the TSX Company Manual, principally by consolidating sections 473 and 475.', 'In July 2000, the Toronto Stock Exchange (the “TSX”), the TSX Venture Exchange and the Canadian Institute of Chartered Accountants mandated the Joint Committee on Corporate Governance (the “JCCG”) to review the state of corporate governance practices in Canada and recommend changes that will assure the ongoing development of Canadian corporate governance standards as among the best in the world. The JCCG tabled its preliminary report in March 2001 and, following extensive comments from various stakeholders, issued its final report in November 2001 (the “JCCG Report”). The Joint Committee on Corporate Governance Report contains 15 recommendations, the majority of which propose modifications to the existing TSX Corporate Governance Guidelines (the “Guidelines”) introduced in 1995. In response, the TSX is proposing that certain amendments be made to the Guidelines. Other recommendations of the JCCG will be reflected in Practice Notes to the Guidelines. The TSX has also amended the disclosure requirements in the TSX Company Manual, principally by consolidating sections 473 and 475.', 'Canada', 'climate', 'in_force', '2002-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_32', ARRAY['guidance_frameworks', 'sdg16', 'canada', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4837e280-fa1b-5692-b85f-29c6c87ef4e9', 'Canada Beyond Compliance: Building a Governance Culture (Saucier Report)', 'Beyond Compliance: Building a Governance Culture (Saucier Report)', 'In Canada, the 1994 report of the Dey Committee, and subsequent TSE disclosure requirements and governance guidelines, set down a strong foundation for effective corporate governance. This report builds on that foundation. The focus is on ways to improve governance without losing sight of our corporations’ need for competitiveness in the global economy. The report’s recommendations go beyond compliance and propose guidelines, principles and practices that will help directors build healthy corporate cultures in the boardroom, where it counts.', 'In Canada, the 1994 report of the Dey Committee, and subsequent TSE disclosure requirements and governance guidelines, set down a strong foundation for effective corporate governance. This report builds on that foundation. The focus is on ways to improve governance without losing sight of our corporations’ need for competitiveness in the global economy. The report’s recommendations go beyond compliance and propose guidelines, principles and practices that will help directors build healthy corporate cultures in the boardroom, where it counts.', 'In Canada, the 1994 report of the Dey Committee, and subsequent TSE disclosure requirements and governance guidelines, set down a strong foundation for effective corporate governance. This report builds on that foundation. The focus is on ways to improve governance without losing sight of our corporations’ need for competitiveness in the global economy. The report’s recommendations go beyond compliance and propose guidelines, principles and practices that will help directors build healthy corporate cultures in the boardroom, where it counts.', 'Canada', 'climate', 'in_force', '2001-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_22', ARRAY['mandatory', 'sdg16', 'mandatory_regulations', 'canada', 'disclosure', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('9a2f5ee0-d579-52eb-88db-b1cb5cc94c5c', 'Canada Canadian Environmental Protection Act', 'The Canadian Environmental Protection Act', 'The Canadian Environmental Protection Act, 1999 (CEPA) is a federal law in Canada that establishes a framework for the protection and conservation of the environment and human health. The Act places obligations on businesses to manage and reduce the environmental and health impacts of their activities. Businesses are required to comply with a range of regulations, guidelines, and codes of practice designed to prevent and manage environmental pollution and health risks, including those related to toxic substances, hazardous waste, and air and water pollution. Under CEPA, businesses are required to report on the release of toxic substances into the environment and implement measures to manage and reduce these releases. The Act also empowers the government to issue orders and regulations requiring businesses to take actions to prevent and mitigate the effects of pollution and other environmental risks. Additionally, CEPA establishes penalties and enforcement mechanisms to ensure compliance with the Act, including fines, penalties, and imprisonment for non-compliance. Overall, CEPA places significant obligations on businesses to protect the environment and human health, and to comply with regulations and guidelines aimed at reducing environmental pollution and risks.', 'The Canadian Environmental Protection Act, 1999 (CEPA) is a federal law in Canada that establishes a framework for the protection and conservation of the environment and human health. The Act places obligations on businesses to manage and reduce the environmental and health impacts of their activities. Businesses are required to comply with a range of regulations, guidelines, and codes of practice designed to prevent and manage environmental pollution and health risks, including those related to toxic substances, hazardous waste, and air and water pollution. Under CEPA, businesses are required to report on the release of toxic substances into the environment and implement measures to manage and reduce these releases. The Act also empowers the government to issue orders and regulations requiring businesses to take actions to prevent and mitigate the effects of pollution and other environmental risks. Additionally, CEPA establishes penalties and enforcement mechanisms to ensure compliance with the Act, including fines, penalties, and imprisonment for non-compliance. Overall, CEPA places significant obligations on businesses to protect the environment and human health, and to comply with regulations and guidelines aimed at reducing environmental pollution and risks.', 'The Canadian Environmental Protection Act, 1999 (CEPA) is a federal law in Canada that establishes a framework for the protection and conservation of the environment and human health. The Act places obligations on businesses to manage and reduce the environmental and health impacts of their activities. Businesses are required to comply with a range of regulations, guidelines, and codes of practice designed to prevent and manage environmental pollution and health risks, including those related to toxic substances, hazardous waste, and air and water pollution. Under CEPA, businesses are required to report on the release of toxic substances into the environment and implement measures to manage and reduce these releases. The Act also empowers the government to issue orders and regulations requiring businesses to take actions to prevent and mitigate the effects of pollution and other environmental risks. Additionally, CEPA establishes penalties and enforcement mechanisms to ensure compliance with the Act, including fines, penalties, and imprisonment for non-compliance. Overall, CEPA places significant obligations on businesses to protect the environment and human health, and to comply with regulations and guidelines aimed at reducing environmental pollution and risks.', 'Canada', 'climate', 'in_force', '1999-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_27', ARRAY['regulations', 'mandatory', 'sdg6', 'canada', 'disclosure', 'sdg12', 'sdg9', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('46428916-7876-5b12-9366-b7015b31ce77', 'Canada Building on Strength: Improving Governance and Accountability', 'Building on Strength: Improving Governance and Accountability in Canada''s Voluntary Sector', 'Canada''s voluntary sector, consisting of approximately 175,000 organizations, is remarkably strong. In order to thrive in a dramatically changed environment and to maintain the high levels of confidence which Canadians have for the sector, it will need to ensure that its governance mechanisms are up to the task and that accountability is both effective and seen to be effective. The Panel on Accountability and Governance in the Voluntary Sector was an initiative of the sector for the sector to aid in this process of adapting to change. In the fall of 1997, the Voluntary Sector Roundtable, an unincorporated group of national voluntary organizations, appointed six individuals, serving as volunteers, to lead a review with a threefold mandate: (1) to conduct research and present draft proposals for discussion about how to promote accountability and governance in the voluntary sector;  (2) to get feedback from the sector by leading broad consultations; (3) and to present a final report containing specific recommendations.', 'Canada''s voluntary sector, consisting of approximately 175,000 organizations, is remarkably strong. In order to thrive in a dramatically changed environment and to maintain the high levels of confidence which Canadians have for the sector, it will need to ensure that its governance mechanisms are up to the task and that accountability is both effective and seen to be effective. The Panel on Accountability and Governance in the Voluntary Sector was an initiative of the sector for the sector to aid in this process of adapting to change. In the fall of 1997, the Voluntary Sector Roundtable, an unincorporated group of national voluntary organizations, appointed six individuals, serving as volunteers, to lead a review with a threefold mandate: (1) to conduct research and present draft proposals for discussion about how to promote accountability and governance in the voluntary sector;  (2) to get feedback from the sector by leading broad consultations; (3) and to present a final report containing specific recommendations.', 'Canada''s voluntary sector, consisting of approximately 175,000 organizations, is remarkably strong. In order to thrive in a dramatically changed environment and to maintain the high levels of confidence which Canadians have for the sector, it will need to ensure that its governance mechanisms are up to the task and that accountability is both effective and seen to be effective. The Panel on Accountability and Governance in the Voluntary Sector was an initiative of the sector for the sector to aid in this process of adapting to change. In the fall of 1997, the Voluntary Sector Roundtable, an unincorporated group of national voluntary organizations, appointed six individuals, serving as volunteers, to lead a review with a threefold mandate: (1) to conduct research and present draft proposals for discussion about how to promote accountability and governance in the voluntary sector;  (2) to get feedback from the sector by leading broad consultations; (3) and to present a final report containing specific recommendations.', 'Canada', 'climate', 'in_force', '1999-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_28', ARRAY['guidance_frameworks', 'sdg14', 'sdg16', 'canada', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('03b2371b-279d-5727-b19d-e11f0c0f7440', 'Canada Report on Corporate Governance, 1999. Five Years', 'Report on Corporate Governance, 1999. Five Years to the Dey', 'Under the leadership of Peter J. Dey, a prominent lawyer and one-time chairman of the Ontario Securities Commission, the TSE''s Corporate Governance Committee report heralded a new era of increased attention to the responsibilities of Canadian boards as stewards of shareholder value. The TSE adopted the Committee''s 14 recommendations as best practice guidelines for listed companies. To that end, the TSE and the Institute of Corporate Directors (ICD) undertook this Five Years to the Dey survey of the current state of corporate governance among TSE-listed companies. Many of the largest companies that account for the greatest proportion of Canadian equity investment are leaders in corporate governance.', 'Under the leadership of Peter J. Dey, a prominent lawyer and one-time chairman of the Ontario Securities Commission, the TSE''s Corporate Governance Committee report heralded a new era of increased attention to the responsibilities of Canadian boards as stewards of shareholder value. The TSE adopted the Committee''s 14 recommendations as best practice guidelines for listed companies. To that end, the TSE and the Institute of Corporate Directors (ICD) undertook this Five Years to the Dey survey of the current state of corporate governance among TSE-listed companies. Many of the largest companies that account for the greatest proportion of Canadian equity investment are leaders in corporate governance.', 'Under the leadership of Peter J. Dey, a prominent lawyer and one-time chairman of the Ontario Securities Commission, the TSE''s Corporate Governance Committee report heralded a new era of increased attention to the responsibilities of Canadian boards as stewards of shareholder value. The TSE adopted the Committee''s 14 recommendations as best practice guidelines for listed companies. To that end, the TSE and the Institute of Corporate Directors (ICD) undertook this Five Years to the Dey survey of the current state of corporate governance among TSE-listed companies. Many of the largest companies that account for the greatest proportion of Canadian equity investment are leaders in corporate governance.', 'Canada', 'climate', 'in_force', '1999-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_33', ARRAY['sdg4', 'mandatory', 'sdg16', 'mandatory_regulations', 'canada', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('92550cd4-64b3-5e21-9fa9-52357fee8ba5', 'Canada National Pollutant Release Inventory (NPRI)', 'National Pollutant Release Inventory (NPRI)', 'The National Pollutant Release Inventory (NPRI) provides Canadians with facility-specific information regarding the release (to air, water, and land), disposal and recycling of more than 300 substances. These include substances that meet the criteria under section 64 of the Canadian Environmental Protection Act, 1999 (CEPA) (that is, toxic substances), pollutants that contribute to smog, poor air quality and acid rain (that is, air pollutants), and other substances of concern.', 'The National Pollutant Release Inventory (NPRI) provides Canadians with facility-specific information regarding the release (to air, water, and land), disposal and recycling of more than 300 substances. These include substances that meet the criteria under section 64 of the Canadian Environmental Protection Act, 1999 (CEPA) (that is, toxic substances), pollutants that contribute to smog, poor air quality and acid rain (that is, air pollutants), and other substances of concern.', 'The National Pollutant Release Inventory (NPRI) provides Canadians with facility-specific information regarding the release (to air, water, and land), disposal and recycling of more than 300 substances. These include substances that meet the criteria under section 64 of the Canadian Environmental Protection Act, 1999 (CEPA) (that is, toxic substances), pollutants that contribute to smog, poor air quality and acid rain (that is, air pollutants), and other substances of concern.', 'Canada', 'nature', 'in_force', '1999-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_4', ARRAY['regulations', 'sdg9', 'mandatory', 'sdg6', 'canada', 'disclosure', 'sdg12', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('379e636d-8e47-5f92-8278-587a4d870160', 'Canada Canadian Environmental Protection Act, 1999 (S.C. 1999, c', 'Canadian Environmental Protection Act, 1999 (S.C. 1999, c. 33)', 'The primary purpose of the Canadian Environmental Protection Act, 1999 (CEPA) is to contribute to sustainable development through pollution prevention. It provides the legislative basis for a range of federal environmental and health protection programs. These include activities related to: (1) the assessment and management of risks from chemicals, polymers and living organisms; (2) programs related to air and water pollution, hazardous waste, air pollutant and greenhouse gas emissions; (3) ocean disposal and environmental emergencies.', 'The primary purpose of the Canadian Environmental Protection Act, 1999 (CEPA) is to contribute to sustainable development through pollution prevention. It provides the legislative basis for a range of federal environmental and health protection programs. These include activities related to: (1) the assessment and management of risks from chemicals, polymers and living organisms; (2) programs related to air and water pollution, hazardous waste, air pollutant and greenhouse gas emissions; (3) ocean disposal and environmental emergencies.', 'The primary purpose of the Canadian Environmental Protection Act, 1999 (CEPA) is to contribute to sustainable development through pollution prevention. It provides the legislative basis for a range of federal environmental and health protection programs. These include activities related to: (1) the assessment and management of risks from chemicals, polymers and living organisms; (2) programs related to air and water pollution, hazardous waste, air pollutant and greenhouse gas emissions; (3) ocean disposal and environmental emergencies.', 'Canada', 'climate', 'in_force', '1999-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_5', ARRAY['sdg13', 'sdg14', 'regulations', 'mandatory', 'sdg6', 'canada', 'disclosure', 'sdg12', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5404e017-5d9e-54bf-b431-e360b1615fe9', '2025 Updates CDP Corporate Questionnaires and Scoring Methodologies', '2025 Updates CDP Corporate Questionnaires and Scoring Methodologies', 'This policy was published in 2025 by Carbon Disclosure Project (CDP). It addresses sustainability and corporate responsibility requirements.', 'This policy was published in 2025 by Carbon Disclosure Project (CDP). It addresses sustainability and corporate responsibility requirements.', 'This policy was published in 2025 by Carbon Disclosure Project (CDP). It addresses sustainability and corporate responsibility requirements.', 'CDP', 'climate', 'in_force', '2025-01-01'::date, 'CDP', 'https://assets.ctfassets.net/v7uy4j80khf8/6pAPMxuMw8vRfnuqwNlIZI/62e0561378add581029c7f0a51b1c104/CDP_Corporate_Questionnaires_and_Scoring_Methodologies_Updates_2025.pdf', ARRAY['cdp', 'voluntary_frameworks', 'sdg13', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4d5d0815-f704-5868-a747-e589e3bf505d', 'CDP City-Business Climate Alliances. A step-by-step guide for developing', 'City-Business Climate Alliances. A step-by-step guide for developing successful collaborations', 'This guide aims to give cities a better understanding of their climate-related goals that need private sector collaboration, which to prioritize and which partners are best placed to help them achieve these. Cities will also be equipped with the knowledge to create partnerships that are well-governed, financially viable and which facilitate further and faster action on climate change.', 'This guide aims to give cities a better understanding of their climate-related goals that need private sector collaboration, which to prioritize and which partners are best placed to help them achieve these. Cities will also be equipped with the knowledge to create partnerships that are well-governed, financially viable and which facilitate further and faster action on climate change.', 'This guide aims to give cities a better understanding of their climate-related goals that need private sector collaboration, which to prioritize and which partners are best placed to help them achieve these. Cities will also be equipped with the knowledge to create partnerships that are well-governed, financially viable and which facilitate further and faster action on climate change.', 'CDP', 'climate', 'in_force', '2019-01-01'::date, 'C40 Knowledge Hub (hosting CDP guide)', 'https://www.c40knowledgehub.org/s/article/City-Business-Climate-Alliances-A-step-by-step-guide-for-developing-successful-collaborations?language=en_US', ARRAY['sdg13', 'other sustainability policy', 'regulations', 'sdg17', 'sdg11', 'cdp', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ce1f0022-6b73-56e0-8b44-0cdef3020f99', 'Chad Labor Code, 1996 (Law PR/96)', 'Labor Code, 1996 (Law no. 038/PR/96).', 'Enacted in 1996, this law safeguards worker rights and regulates employment in Chad. Covering areas like work hours, safety, and collective bargaining, it forms the foundation of the country''s labor legal framework. Amended over time, especially in 2015 to strengthen protections against unfair dismissal and improve conditions for women and children, the code remains a key contributor to promoting fair labor practices in Chad.', 'Enacted in 1996, this law safeguards worker rights and regulates employment in Chad. Covering areas like work hours, safety, and collective bargaining, it forms the foundation of the country''s labor legal framework. Amended over time, especially in 2015 to strengthen protections against unfair dismissal and improve conditions for women and children, the code remains a key contributor to promoting fair labor practices in Chad.', 'Enacted in 1996, this law safeguards worker rights and regulates employment in Chad. Covering areas like work hours, safety, and collective bargaining, it forms the foundation of the country''s labor legal framework. Amended over time, especially in 2015 to strengthen protections against unfair dismissal and improve conditions for women and children, the code remains a key contributor to promoting fair labor practices in Chad.', 'Chad', 'social', 'in_force', '1996-01-01'::date, 'Chad', 'https://www.carrotsandsticks.org/policies/30_1', ARRAY['sdg8', 'other sustainability policy', 'regulations', 'mandatory', 'sdg5', 'chad']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f0d065e6-d121-5329-af3b-3b11d8becc42', 'Chile’s Sustainability Linked Bond Framework. June', 'Chile’s Sustainability Linked Bond Framework. June 2023', 'Chile''s Sustainability-Linked Bond Framework, updated in June 2023, provides a roadmap for issuing bonds where financial terms are tied to achieving pre-defined sustainability targets. This revision enhances the framework''s alignment with international best practices and transparency.', 'Chile''s Sustainability-Linked Bond Framework, updated in June 2023, provides a roadmap for issuing bonds where financial terms are tied to achieving pre-defined sustainability targets. This revision enhances the framework''s alignment with international best practices and transparency.', 'Chile''s Sustainability-Linked Bond Framework, updated in June 2023, provides a roadmap for issuing bonds where financial terms are tied to achieving pre-defined sustainability targets. This revision enhances the framework''s alignment with international best practices and transparency.', 'Chile', 'climate', 'in_force', '2023-01-01'::date, 'Chile', 'https://www.carrotsandsticks.org/policies/32_54', ARRAY['other sustainability policy', 'sdg7', 'voluntary', 'chile', 'sdg16', 'sdg9', 'voluntary_frameworks']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('94361b09-8994-527f-b493-87ad5c8fdd3a', 'Chile’s Sustainability-Linked Bond Framework. February', 'Chile’s Sustainability-Linked Bond Framework. February 2022', 'In February 2022, Chile published a Sustainability- Linked Bond Framework (SLB Framework), becoming the first-ever sovereign to issue Sustainability-Linked Bonds in March 2022, with a landmark transaction that aligned economic incentives with the achievement of ambitious sustainability targets.', 'In February 2022, Chile published a Sustainability- Linked Bond Framework (SLB Framework), becoming the first-ever sovereign to issue Sustainability-Linked Bonds in March 2022, with a landmark transaction that aligned economic incentives with the achievement of ambitious sustainability targets.', 'In February 2022, Chile published a Sustainability- Linked Bond Framework (SLB Framework), becoming the first-ever sovereign to issue Sustainability-Linked Bonds in March 2022, with a landmark transaction that aligned economic incentives with the achievement of ambitious sustainability targets.', 'Chile', 'climate', 'in_force', '2022-01-01'::date, 'Chile', 'https://www.carrotsandsticks.org/policies/32_53', ARRAY['sdg13', 'other sustainability policy', 'sdg9', 'sdg7', 'voluntary', 'chile', 'sdg15', 'voluntary_frameworks']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c4526798-430e-5d6d-bf01-3998898b6901', 'Chile General Regulation . Modifies the structure and content', 'General Regulation No. 461. Modifies the structure and content of the annual report of the issuers of securities and modifies and repeals regulations that indicate', 'Norma De Carácter General N°461 modifies the structure and content of the annual report that issuers of securities must provide, and repeals and modifies certain related regulations. The new regulation specifies the information that issuers must include in their annual reports, such as financial statements, a management report, a corporate governance report, and other relevant information. The regulation also establishes requirements for the presentation of this information, such as the use of plain language and the inclusion of key performance indicators. The goal of the regulation is to increase transparency and enhance the quality of information provided to investors.', 'Norma De Carácter General N°461 modifies the structure and content of the annual report that issuers of securities must provide, and repeals and modifies certain related regulations. The new regulation specifies the information that issuers must include in their annual reports, such as financial statements, a management report, a corporate governance report, and other relevant information. The regulation also establishes requirements for the presentation of this information, such as the use of plain language and the inclusion of key performance indicators. The goal of the regulation is to increase transparency and enhance the quality of information provided to investors.', 'Norma De Carácter General N°461 modifies the structure and content of the annual report that issuers of securities must provide, and repeals and modifies certain related regulations. The new regulation specifies the information that issuers must include in their annual reports, such as financial statements, a management report, a corporate governance report, and other relevant information. The regulation also establishes requirements for the presentation of this information, such as the use of plain language and the inclusion of key performance indicators. The goal of the regulation is to increase transparency and enhance the quality of information provided to investors.', 'Chile', 'climate', 'in_force', '2021-01-01'::date, 'Chile', 'https://www.carrotsandsticks.org/policies/32_50', ARRAY['sdg10', 'regulations', 'mandatory', 'chile', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b56bd28d-38bc-5317-be27-10f3d09e80b6', 'Sustainability reporting and disclosure guide for issuers in Chile', 'Sustainability reporting and disclosure guide for issuers in Chile', 'The Guía de Reporte y Divulgación de Sostenibilidad para Emisores en Chile provides guidance for companies in Chile on how to report and disclose their sustainability practices. The guide outlines the principles, frameworks, and standards that companies can use to report on their environmental, social, and governance (ESG) performance. It also provides specific guidance on how to disclose information related to topics such as climate change, human rights, and supply chain management. The goal of the guide is to promote transparency and accountability among companies and to help investors make informed decisions based on ESG considerations.', 'The Guía de Reporte y Divulgación de Sostenibilidad para Emisores en Chile provides guidance for companies in Chile on how to report and disclose their sustainability practices. The guide outlines the principles, frameworks, and standards that companies can use to report on their environmental, social, and governance (ESG) performance. It also provides specific guidance on how to disclose information related to topics such as climate change, human rights, and supply chain management. The goal of the guide is to promote transparency and accountability among companies and to help investors make informed decisions based on ESG considerations.', 'The Guía de Reporte y Divulgación de Sostenibilidad para Emisores en Chile provides guidance for companies in Chile on how to report and disclose their sustainability practices. The guide outlines the principles, frameworks, and standards that companies can use to report on their environmental, social, and governance (ESG) performance. It also provides specific guidance on how to disclose information related to topics such as climate change, human rights, and supply chain management. The goal of the guide is to promote transparency and accountability among companies and to help investors make informed decisions based on ESG considerations.', 'Chile', 'climate', 'in_force', '2021-01-01'::date, 'Chile', 'https://www.carrotsandsticks.org/policies/32_51', ARRAY['sdg13', 'mandatory', 'chile', 'sdg16', 'mandatory_regulations', 'sdg12', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('76ccaf40-e61c-503a-8174-ab2586139a3f', 'Chile Green Tax Reform (Ley 21.210)', 'Green Tax Reform (Ley 21.210)', 'Chile implemented a green tax system in 2014 under Law 20.780, marking a significant step towards environmentally responsible fiscal policy. This system imposes taxes on emissions of local pollutants (particulate matter, nitrogen oxides, sulfur dioxide) and global pollutants (carbon dioxide) from stationary sources like power plants. The tax is calculated based on actual emissions from facilities, making it a downstream taxation mechanism, unlike the upstream carbon content-based taxes used in other countries.', 'Chile implemented a green tax system in 2014 under Law 20.780, marking a significant step towards environmentally responsible fiscal policy. This system imposes taxes on emissions of local pollutants (particulate matter, nitrogen oxides, sulfur dioxide) and global pollutants (carbon dioxide) from stationary sources like power plants. The tax is calculated based on actual emissions from facilities, making it a downstream taxation mechanism, unlike the upstream carbon content-based taxes used in other countries.', 'Chile implemented a green tax system in 2014 under Law 20.780, marking a significant step towards environmentally responsible fiscal policy. This system imposes taxes on emissions of local pollutants (particulate matter, nitrogen oxides, sulfur dioxide) and global pollutants (carbon dioxide) from stationary sources like power plants. The tax is calculated based on actual emissions from facilities, making it a downstream taxation mechanism, unlike the upstream carbon content-based taxes used in other countries.', 'Chile', 'climate', 'in_force', '2020-01-01'::date, 'Chile', 'https://www.carrotsandsticks.org/policies/32_1', ARRAY['sdg13', 'regulations', 'sdg7', 'mandatory', 'chile', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3a8716c3-efd6-588a-b471-a5a34fc35a25', 'Chilean National Strategy for Climate Change and Low', 'Chilean National Strategy for Climate Change and Low Carbon Development 2020-2050', 'Chile''s Long-Term Climate Strategy (ECLP) presents a comprehensive roadmap for achieving carbon neutrality and climate resilience by 2050. The strategy emphasizes a multisectoral transformation, aiming to drastically reduce greenhouse gas emissions and adapt to climate impacts. Key to the plan are mandatory sectoral emission limits, with a binding goal of carbon neutrality outlined in the newly passed Framework Law on Climate Change. The strategy targets a national carbon emissions budget for 2020-2030, setting a maximum of 1.1 billion tons of CO2e. By 2025, the country''s peak emissions will be reached, marking a significant milestone in the journey toward carbon neutrality. The strategy''s principles include transparent climate governance, cost-effectiveness, the promotion of nature-based solutions, a social pillar centered on just transitions, and alignment with the UN’s Sustainable Development Goals (SDGs). An inclusive and participatory process, involving over 4,000 citizens and stakeholders, has informed the strategy''s formulation. The strategy is integrated into a broader legal framework, with climate action plans to be implemented by various sectors.', 'Chile''s Long-Term Climate Strategy (ECLP) presents a comprehensive roadmap for achieving carbon neutrality and climate resilience by 2050. The strategy emphasizes a multisectoral transformation, aiming to drastically reduce greenhouse gas emissions and adapt to climate impacts. Key to the plan are mandatory sectoral emission limits, with a binding goal of carbon neutrality outlined in the newly passed Framework Law on Climate Change. The strategy targets a national carbon emissions budget for 2020-2030, setting a maximum of 1.1 billion tons of CO2e. By 2025, the country''s peak emissions will be reached, marking a significant milestone in the journey toward carbon neutrality. The strategy''s principles include transparent climate governance, cost-effectiveness, the promotion of nature-based solutions, a social pillar centered on just transitions, and alignment with the UN’s Sustainable Development Goals (SDGs). An inclusive and participatory process, involving over 4,000 citizens and stakeholders, has informed the strategy''s formulation. The strategy is integrated into a broader legal framework, with climate action plans to be implemented by various sectors.', 'Chile''s Long-Term Climate Strategy (ECLP) presents a comprehensive roadmap for achieving carbon neutrality and climate resilience by 2050. The strategy emphasizes a multisectoral transformation, aiming to drastically reduce greenhouse gas emissions and adapt to climate impacts. Key to the plan are mandatory sectoral emission limits, with a binding goal of carbon neutrality outlined in the newly passed Framework Law on Climate Change. The strategy targets a national carbon emissions budget for 2020-2030, setting a maximum of 1.1 billion tons of CO2e. By 2025, the country''s peak emissions will be reached, marking a significant milestone in the journey toward carbon neutrality. The strategy''s principles include transparent climate governance, cost-effectiveness, the promotion of nature-based solutions, a social pillar centered on just transitions, and alignment with the UN’s Sustainable Development Goals (SDGs). An inclusive and participatory process, involving over 4,000 citizens and stakeholders, has informed the strategy''s formulation. The strategy is integrated into a broader legal framework, with climate action plans to be implemented by various sectors.', 'Chile', 'climate', 'in_force', '2020-01-01'::date, 'Chile', 'https://www.carrotsandsticks.org/policies/32_2', ARRAY['sdg13', 'sdg7', 'mandatory', 'chile', 'sdg16', 'mandatory_regulations', 'sdg15', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8e07b1e9-cbb4-5be1-af5b-733792feb17f', 'Chile''s Nationally Determined Contribution, Update', 'Chile''s Nationally Determined Contribution, Update 2020', 'Chile''s Nationally Determined Contribution (NDC) Update 2020 outlines the country''s commitment to reducing its greenhouse gas emissions by 45% below 2010 levels by 2030. The NDC includes sectoral targets for energy, transportation, industry, waste, and forestry, with measures to promote renewable energy, electrification of public transportation, and energy efficiency in buildings. Chile also aims to increase the amount of forested land and reduce deforestation and forest degradation. The NDC update emphasizes the importance of international cooperation and support to achieve these goals and highlights the potential benefits of climate action, such as job creation and public health improvements.', 'Chile''s Nationally Determined Contribution (NDC) Update 2020 outlines the country''s commitment to reducing its greenhouse gas emissions by 45% below 2010 levels by 2030. The NDC includes sectoral targets for energy, transportation, industry, waste, and forestry, with measures to promote renewable energy, electrification of public transportation, and energy efficiency in buildings. Chile also aims to increase the amount of forested land and reduce deforestation and forest degradation. The NDC update emphasizes the importance of international cooperation and support to achieve these goals and highlights the potential benefits of climate action, such as job creation and public health improvements.', 'Chile''s Nationally Determined Contribution (NDC) Update 2020 outlines the country''s commitment to reducing its greenhouse gas emissions by 45% below 2010 levels by 2030. The NDC includes sectoral targets for energy, transportation, industry, waste, and forestry, with measures to promote renewable energy, electrification of public transportation, and energy efficiency in buildings. Chile also aims to increase the amount of forested land and reduce deforestation and forest degradation. The NDC update emphasizes the importance of international cooperation and support to achieve these goals and highlights the potential benefits of climate action, such as job creation and public health improvements.', 'Chile', 'climate', 'in_force', '2020-01-01'::date, 'Chile', 'https://www.carrotsandsticks.org/policies/32_52', ARRAY['sdg13', 'other sustainability policy', 'regulations', 'sdg7', 'mandatory', 'chile', 'sdg12', 'sdg15', 'sdg9', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b099571e-c0e3-5e9f-9327-36bfc8d6de20', 'Chile’s Sustainable Bond Framework. November', 'Chile’s Sustainable Bond Framework. November 2020', 'Chile''s 2020 Sustainable Bond Framework raises funds for green (clean transport, renewable energy) and social (education, elderly support) projects. It directs investment towards initiatives aligned with the nation''s sustainability goals, attracting investors seeking to back impactful projects directly while driving positive environmental and social change. This framework, distinct from the 2023 Sustainability-Linked Bond Framework, focuses on project allocation rather than performance-linked incentives.', 'Chile''s 2020 Sustainable Bond Framework raises funds for green (clean transport, renewable energy) and social (education, elderly support) projects. It directs investment towards initiatives aligned with the nation''s sustainability goals, attracting investors seeking to back impactful projects directly while driving positive environmental and social change. This framework, distinct from the 2023 Sustainability-Linked Bond Framework, focuses on project allocation rather than performance-linked incentives.', 'Chile''s 2020 Sustainable Bond Framework raises funds for green (clean transport, renewable energy) and social (education, elderly support) projects. It directs investment towards initiatives aligned with the nation''s sustainability goals, attracting investors seeking to back impactful projects directly while driving positive environmental and social change. This framework, distinct from the 2023 Sustainability-Linked Bond Framework, focuses on project allocation rather than performance-linked incentives.', 'Chile', 'climate', 'in_force', '2020-01-01'::date, 'Chile', 'https://www.carrotsandsticks.org/policies/32_55', ARRAY['sdg4', 'sdg3', 'sdg13', 'other sustainability policy', 'sdg7', 'sdg11', 'voluntary', 'chile', 'sdg1', 'voluntary_frameworks']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('96c2c7f7-c42f-5e13-b44f-716cf42e50e3', 'Chile National Action Plan on Sustainable Consumption and Production', 'National Action Plan on Sustainable Consumption and Production "2017-2022"', 'The Action Plan constitutes the second stage of an effort to coordinate the initiatives of the State, disseminating and committing the concrete actions that the public and private sectors have initiated to increase efficiency and productivity throughout the supply chain and the life cycle of products and services, now and in the long term. This Plan constitutes a framework of agreed and relevant activities to implement the national program, thus strengthening our commitment to green growth and a circular economy.', 'The Action Plan constitutes the second stage of an effort to coordinate the initiatives of the State, disseminating and committing the concrete actions that the public and private sectors have initiated to increase efficiency and productivity throughout the supply chain and the life cycle of products and services, now and in the long term. This Plan constitutes a framework of agreed and relevant activities to implement the national program, thus strengthening our commitment to green growth and a circular economy.', 'The Action Plan constitutes the second stage of an effort to coordinate the initiatives of the State, disseminating and committing the concrete actions that the public and private sectors have initiated to increase efficiency and productivity throughout the supply chain and the life cycle of products and services, now and in the long term. This Plan constitutes a framework of agreed and relevant activities to implement the national program, thus strengthening our commitment to green growth and a circular economy.', 'Chile', 'climate', 'in_force', '2017-01-01'::date, 'Chile', 'https://www