INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d3f54d7b-580f-54a1-bd29-64fe7b6ce01f', 'Chile How to include ESG factors: design and construction', 'How to include ESG factors: design and construction of sustainability reports', 'The Sustainability Reporting Guide is designed to help issuers prepare and publish information related to environmental, social and governance (ESG) matters.', 'The Sustainability Reporting Guide is designed to help issuers prepare and publish information related to environmental, social and governance (ESG) matters.', 'The Sustainability Reporting Guide is designed to help issuers prepare and publish information related to environmental, social and governance (ESG) matters.', 'Chile', 'climate', 'in_force', '2017-01-01'::date, 'Chile', 'https://www.carrotsandsticks.org/policies/32_5', ARRAY['other sustainability policy', 'regulations', 'sdg7', 'mandatory', 'chile', 'sdg16', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8b453575-57d8-590a-9f5a-b8aefa5a5225', 'Chile Guide on Responsible Investment', 'Guide on Responsible Investment 2017', 'This guide is intended to provide information about the concept and context of investment responsible to the general public, as well as provide guidance to institutional investors and financial and investment analysts, to that can develop in this new trend by incorporating ESG aspects into investment processes.', 'This guide is intended to provide information about the concept and context of investment responsible to the general public, as well as provide guidance to institutional investors and financial and investment analysts, to that can develop in this new trend by incorporating ESG aspects into investment processes.', 'This guide is intended to provide information about the concept and context of investment responsible to the general public, as well as provide guidance to institutional investors and financial and investment analysts, to that can develop in this new trend by incorporating ESG aspects into investment processes.', 'Chile', 'climate', 'in_force', '2017-01-01'::date, 'Chile', 'https://www.carrotsandsticks.org/policies/32_57', ARRAY['guidance_frameworks', 'sdg13', 'mandatory', 'chile', 'sdg16', 'sdg12', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c480c87e-1fef-54bd-8aa4-68296d6af753', 'Chile Company and Human Rights', 'The Company and Human Rights', 'In 2016, Chile introduced the "La Empresa y los Derechos Humanos" ("Business and Human Rights") policy, which sets out the obligations of businesses in relation to human rights. The policy is based on the United Nations Guiding Principles on Business and Human Rights and emphasizes the responsibility of businesses to respect human rights, to carry out due diligence to identify and address human rights risks, and to provide effective remedies for any human rights abuses that may occur. The policy requires businesses to develop human rights policies and to implement mechanisms to monitor and report on their human rights performance. Businesses must also engage in meaningful consultation with stakeholders, including affected communities and human rights organizations, to identify and address human rights risks. The policy applies to all businesses operating in Chile, regardless of their size or sector, and is enforced by the Chilean government through various regulatory mechanisms.', 'In 2016, Chile introduced the "La Empresa y los Derechos Humanos" ("Business and Human Rights") policy, which sets out the obligations of businesses in relation to human rights. The policy is based on the United Nations Guiding Principles on Business and Human Rights and emphasizes the responsibility of businesses to respect human rights, to carry out due diligence to identify and address human rights risks, and to provide effective remedies for any human rights abuses that may occur. The policy requires businesses to develop human rights policies and to implement mechanisms to monitor and report on their human rights performance. Businesses must also engage in meaningful consultation with stakeholders, including affected communities and human rights organizations, to identify and address human rights risks. The policy applies to all businesses operating in Chile, regardless of their size or sector, and is enforced by the Chilean government through various regulatory mechanisms.', 'In 2016, Chile introduced the "La Empresa y los Derechos Humanos" ("Business and Human Rights") policy, which sets out the obligations of businesses in relation to human rights. The policy is based on the United Nations Guiding Principles on Business and Human Rights and emphasizes the responsibility of businesses to respect human rights, to carry out due diligence to identify and address human rights risks, and to provide effective remedies for any human rights abuses that may occur. The policy requires businesses to develop human rights policies and to implement mechanisms to monitor and report on their human rights performance. Businesses must also engage in meaningful consultation with stakeholders, including affected communities and human rights organizations, to identify and address human rights risks. The policy applies to all businesses operating in Chile, regardless of their size or sector, and is enforced by the Chilean government through various regulatory mechanisms.', 'Chile', 'climate', 'in_force', '2016-01-01'::date, 'Chile', 'https://www.carrotsandsticks.org/policies/32_13', ARRAY['guidance_frameworks', 'mandatory', 'chile', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('6b1c4a5f-9a7c-5b3c-9a90-5cdcfbdd4cf1', 'Chile General Regulation', 'General Regulation No. 408', 'Norma de Carácter General No. 408 was issued by the Superintendence of Securities and Insurance of Chile in 2016. It establishes guidelines for insurance companies in Chile to identify, assess, manage, and report risks associated with environmental, social, and governance factors. The focus is on promoting responsible investment practices and considering the impact of such factors on the insurance company''s investments. The norm also requires insurance companies to disclose their environmental, social, and governance policies and practices in their annual reports. This norm creates an obligation for insurance companies to incorporate environmental, social, and governance considerations into their investment decisions and to disclose their policies and practices in this regard.', 'Norma de Carácter General No. 408 was issued by the Superintendence of Securities and Insurance of Chile in 2016. It establishes guidelines for insurance companies in Chile to identify, assess, manage, and report risks associated with environmental, social, and governance factors. The focus is on promoting responsible investment practices and considering the impact of such factors on the insurance company''s investments. The norm also requires insurance companies to disclose their environmental, social, and governance policies and practices in their annual reports. This norm creates an obligation for insurance companies to incorporate environmental, social, and governance considerations into their investment decisions and to disclose their policies and practices in this regard.', 'Norma de Carácter General No. 408 was issued by the Superintendence of Securities and Insurance of Chile in 2016. It establishes guidelines for insurance companies in Chile to identify, assess, manage, and report risks associated with environmental, social, and governance factors. The focus is on promoting responsible investment practices and considering the impact of such factors on the insurance company''s investments. The norm also requires insurance companies to disclose their environmental, social, and governance policies and practices in their annual reports. This norm creates an obligation for insurance companies to incorporate environmental, social, and governance considerations into their investment decisions and to disclose their policies and practices in this regard.', 'Chile', 'climate', 'in_force', '2016-01-01'::date, 'Chile', 'https://www.carrotsandsticks.org/policies/32_25', ARRAY['regulations', 'mandatory', 'chile', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
